# INFRASTRUCTURE
import json
import os
import re
import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _fire_log import log_fire

# canonical allowed background form: any sleep-only command — bare "sleep N" or "sleep N && echo <anything>".
# Mirrors _SLEEP_ONLY_BG in rewrite_background_sleep.py; exempts both raw and normalized forms so the
# hook is safe regardless of execution order relative to rewrite_background_sleep.
# [^;&|\n]* stops at shell separators — "sleep N && echo x && other_cmd" is NOT exempt.
# ALL other run_in_background=true commands are foreground-forced — no whitelist.
_CANONICAL = re.compile(r'^\s*sleep\s+\d+(?:\.\d+)?\s*(?:&&\s*echo\b[^;&|\n]*)?\s*$')

# ORCHESTRATOR

# Read Bash tool_input from stdin; silently rewrite run_in_background=true → false for any non-sleep-timer command
def block_unauthorized_background_workflow() -> None:
    command, run_in_background, session_id = _parse_input()
    if not run_in_background:
        sys.exit(0)
    if command is None:
        sys.exit(0)
    if _is_canonical(command):
        sys.exit(0)
    output = _emit_rewrite(command)
    log_fire("block_unauthorized_background", "rewrite", "Bash", command,
             rewritten="run_in_background: true → false", session_id=session_id)
    print(json.dumps(output))
    sys.exit(0)

# FUNCTIONS

# Parse stdin JSON; return (command, run_in_background, session_id); (None, False, None) on error (fail-open)
def _parse_input():
    try:
        payload = json.loads(sys.stdin.read())
        tool_input = payload.get("tool_input", {})
        cmd = tool_input.get("command")
        bg = tool_input.get("run_in_background", False)
        cmd = cmd if isinstance(cmd, str) else None
        bg = bg if isinstance(bg, bool) else False
        return cmd, bg, payload.get("session_id")
    except Exception:
        return None, False, None

# True if command is the canonical background timer (sleep-only)
def _is_canonical(command: str) -> bool:
    return bool(_CANONICAL.match(command))

# Build allow+updatedInput dict flipping run_in_background to false; return it (caller handles print)
def _emit_rewrite(command: str) -> dict:
    return {
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "allow",
            "updatedInput": {
                "command": command,
                "run_in_background": False,
            },
        },
    }


if __name__ == "__main__":
    block_unauthorized_background_workflow()

# INFRASTRUCTURE

# Fast-path marker — cheap contains check before block walk
_BG_LAUNCH_ACK_MARKER = 'running in background with ID'
# Anchored ack prefix: a genuine CC bg-launch ack ALWAYS starts with this exact prefix. The strip
# decision uses startswith() on the lstripped text (NOT substring-anywhere), so a large tool_result
# or user message that merely CONTAINS the phrase as data is never destroyed (was the FP-nuke bug).
_BG_LAUNCH_ACK_PREFIX = 'Command running in background with ID:'


# True only for a genuine bg-launch ack: the marker phrase anchored at the start of the text.
def _is_bg_launch_ack(text):
    return text.lstrip().startswith(_BG_LAUNCH_ACK_PREFIX)


# ORCHESTRATOR

# Replace entire content of any block whose text STARTS WITH the bg-launch-ack prefix with '.'.
# Anchored (not substring-anywhere): legitimate content that merely contains the phrase is kept.
# Covers all 4 content shapes: str, list[text], list[tool_result+str], list[tool_result+list].
# Returns (new_content, removed_chunks) — removed_chunks: original texts of replaced blocks.
def _strip_bg_launch_ack(content):
    removed = []
    if isinstance(content, str):
        if _is_bg_launch_ack(content):
            removed.append(content)
            return 'Command is running in the background. Do NOT check, poll, or read its output — just wait until it finishes (you will get a completion notice).', removed
        return content, removed
    if isinstance(content, list):
        result = []
        for block in content:
            if not isinstance(block, dict):
                result.append(block)
                continue
            btype = block.get('type')
            if btype == 'text':
                text = block.get('text', '')
                if _is_bg_launch_ack(text):
                    removed.append(text)
                    result.append({**block, 'text': 'Command is running in the background. Do NOT check, poll, or read its output — just wait until it finishes (you will get a completion notice).'})
                else:
                    result.append(block)
            elif btype == 'tool_result':
                inner = block.get('content', '')
                if isinstance(inner, str):
                    if _is_bg_launch_ack(inner):
                        removed.append(inner)
                        result.append({**block, 'content': 'Command is running in the background. Do NOT check, poll, or read its output — just wait until it finishes (you will get a completion notice).'})
                    else:
                        result.append(block)
                elif isinstance(inner, list):
                    new_sub = []
                    sub_changed = False
                    for sub in inner:
                        if isinstance(sub, dict) and sub.get('type') == 'text':
                            text = sub.get('text', '')
                            if _is_bg_launch_ack(text):
                                removed.append(text)
                                new_sub.append({**sub, 'text': 'Command is running in the background. Do NOT check, poll, or read its output — just wait until it finishes (you will get a completion notice).'})
                                sub_changed = True
                            else:
                                new_sub.append(sub)
                        else:
                            new_sub.append(sub)
                    result.append({**block, 'content': new_sub} if sub_changed else block)
                else:
                    result.append(block)
            else:
                result.append(block)
        return result, removed
    return content, removed

